import {Envelope} from '../model/interface/envelope.interface';
import {BASE_URL} from './httpClient';
import {
  EkycRepository,
  IEkycHistory,
  IRequestCreateRepo,
  IRequestCreateRepoEId,
  IRequestExcall,
  IRequestSaveData,
} from './interface';

export const createEkycService = (fetchRequest: any) => ({
  async login() {
    const endPoint = '/auth/login';
    try {
      const data = await fetch(
        'https://demo.econtract.kyta.fpt.com/app' + endPoint,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            username: 'nepnhi27@gmail.com',
            password: 'admin@123',
          }),
        },
      );
      return Promise.resolve(data.json());
    } catch (error) {
      return Promise.reject(error);
    }
  },

  async getEnvelopeByIdAndRecipientId(envId: string, recipientId: string) {
    const endpoint = `/services/envelope/api/p/envelope/${envId}?id=${envId}&recipientId=${recipientId}`;
    const response = await fetchRequest({
      url: `${BASE_URL}${endpoint}`,
      method: 'GET',
    });
    return Promise.resolve(response?.data);
  },

  async updateRepositoryDetail(
    envId?: string,
    recpId?: string,
    body?: IRequestSaveData,
  ) {
    const endpoint = `/services/common/api/p/ekyc/${envId}/ekycRepositoryDetails?id=${envId}&recipientId=${recpId}`;
    const response = await fetchRequest({
      url: `${BASE_URL}${endpoint}`,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    });
    return Promise.resolve(response?.data);
  },

  async updateRepository(body: EkycRepository) {
    const endpoint = `/services/common/api/p/ekyc/${body.resourceId}/ekycRepository?id=${body.resourceId}&recipientId=${body.personalId}`;
    const response = await fetchRequest({
      url: `${BASE_URL}${endpoint}`,
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    });
    return Promise.resolve(response?.data);
  },

  async createRepository(body: IRequestCreateRepo) {
    const endpoint = `/services/common/api/p/ekyc/${body.resourceId}/ekycRepository?id=${body.resourceId}&recipientId=${body.personalId}`;
    const response = await fetchRequest({
      url: `${BASE_URL}${endpoint}`,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    });
    return Promise.resolve(response?.data);
  },

  async createRepoEId(body: IRequestCreateRepoEId): Promise<IEkycHistory> {
    const endpoint =
      '/services/eid/api/personal-kyc-detail-profiles-history/create';
    const response = await fetchRequest({
      url: `${BASE_URL}${endpoint}`,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    });
    return Promise.resolve(response?.data);
  },

  async getCaCloudByUserName(envId: string, userName: string) {
    const endpoint = `/services/envelope/api/p/envelope/${envId}/cacloud?username=${userName}`;
    const response = await fetchRequest({
      url: `${BASE_URL}${endpoint}`,
      method: 'GET',
    });
    return Promise.resolve(response?.data);
  },

  async excallApi(body: IRequestExcall) {
    const endpoint = '/services/excall/api/p/excall';
    const response = await fetchRequest({
      url: `${BASE_URL}${endpoint}`,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    });
    return Promise.resolve(response?.data);
  },

  async updateRepoEId(body: IEkycHistory) {
    const endpoint =
      '/services/eid/api/personal-kyc-detail-profiles-history/update';
    const response = await fetchRequest({
      url: `${BASE_URL}${endpoint}`,
      method: 'PUT',
      body: JSON.stringify(body),
    });
    return Promise.resolve(response?.data);
  },
});
