import {isEmpty, isNull, isUndefined} from 'lodash';
import {Envelope} from '../../../../model/interface/envelope.interface';

export const findRecipient = (recipientId: string, envelope: Envelope) => {
  if (isNull(recipientId) || isNull(envelope)) {
    return null;
  }
  if (
    !isUndefined(envelope.requester) &&
    envelope.requester.id === recipientId
  ) {
    return envelope.requester;
  }
  let ret = null;
  if (!isUndefined(envelope.parties)) {
    envelope.parties.forEach(v => {
      if (!isUndefined(v.recipients)) {
        v.recipients.forEach(f => {
          if (f.id === recipientId) {
            ret = f;
          }
        });
      }
    });
  }
  return ret;
};

const personalDocumentTypes = [
  {value: 1, label: 'EY.personal_info.cmtnd', id: 'cmtnd'},
  {value: 2, label: 'EY.personal_info.cccd', id: 'cccd'},
  {value: 3, label: 'EY.personal_info.hc', id: 'hc'},
  {value: 4, label: 'EY.personal_info.ccccchip', id: 'ccccchip'},
];

export const MESSAGETYPES = [
  {id: 'EXPLICIT/OTP-SMS', label: 'EY.personal_info.sms'},
  {id: 'EXPLICIT/OTP-EMAIL', label: 'EY.personal_info.email'},
  {id: 'EXPLICIT/OTP-NOSEND', label: 'EY.personal_info.NOSEND'},
];

export const findPersonalDocumentTypes = (value: any) => {
  if (isUndefined(value) || isNull(value)) {
    return personalDocumentTypes[0].label;
  }
  return personalDocumentTypes.find(item => item.value === value)?.label;
};

export const findMessageTypes = (value: any) => {
  if (isUndefined(value) || isNull(value) || isEmpty(value)) {
    return MESSAGETYPES[0];
  }
  return MESSAGETYPES.find(item => item.id === value);
};
