import {
  ImageBackground,
  Keyboard,
  TouchableWithoutFeedback,
  View,
} from 'react-native';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {SafeAreaView} from 'react-native-safe-area-context';
import {useEffect, useState} from 'react';
import {get, isEmpty} from 'lodash';
import {StackActions, useRoute} from '@react-navigation/native';
import {useAppSelector} from '../../hook/useRedux';
import {useCreateNotiServices} from '../../hook/apiHook/useApi';
import {Recipient} from '../../model/interface/envelope.interface';
import {SignType} from '../../model/interface/notification.interface';
import {NavigationName} from '../../constants';
import Toast from 'react-native-toast-message';
import TextCM from '../../components/Text';
import {
  BgOnboarding,
  EyesIcon,
  EyesIconOpen,
  LogoEcontract,
} from '../../assets/images';
import ButtonCM from '../../components/Button';
import ChangeLanguage from './components/ChangeLanguage';
import {findRecipient} from '../notification/signature-flow/ekyc-flow/helper';
import {useEkycServices} from '../../hook/apiHook/useEkyc';
import TextFieldCM from '../../components/TextField';

const SignAccountOutsideOrganization = ({navigation}: any) => {
  const route = useRoute();
  const {t} = useTranslation();
  const [email, setEmail] = useState<string>('');
  const [errorMessage, setErrorMessage] = useState<string>('');
  const [password, setPassword] = useState<string>('');
  const [errorPassword, setErrorPassword] = useState<string>('');
  const [isSecureText, setIsSecureText] = useState<boolean>(true);
  const [envelopeId, setEnvelopeId] = useState<string>('');
  const [recipientId, setRecipientId] = useState<string>('');
  const isAuthorized = useAppSelector(state => state.common.isAuthorized);

  const NotificationServices = useCreateNotiServices();
  const EkycServices = useEkycServices();

  useEffect(() => {
    setEnvelopeId(get(route, 'params.envelopeId', ''));
    setRecipientId(get(route, 'params.recipientId', ''));
  }, [route]);

  const hideKeyboard = () => {
    Keyboard.dismiss();
  };

  const onAccess = async () => {
    onBlurEmail();
    onBlurAccessCode();
    if (!isEmpty(email) && !isEmpty(password)) {
      const body = {
        email: email.trim(),
        envelopeId: envelopeId,
        password: password.trim(),
        recipientId: recipientId,
      };
      await NotificationServices.getJwtTokenSignature(body).then(async data => {
        if (!isEmpty(data)) {
          const dataResp = await EkycServices.getEnvelopeByIdAndRecipientId(
            data.envelopeId,
            data.recipientId,
          );
          const recipient = findRecipient(
            data.recipientId,
            dataResp.data[0],
          ) as Recipient;
          if (recipient.signTypes?.includes(SignType.EKYC)) {
            navigation.navigate(NavigationName.SignatureWebview, {
              envelopeId: data.envelopeId,
              recipientId: data.recipientId,
              userSign: 'annoymouser',
            });
          } else {
            navigation.navigate(NavigationName.SignatureWebview, {
              envelopeId: data.envelopeId,
              recipientId: data.recipientId,
              userSign: 'annoymouser',
            });
          }
        } else {
          Toast.show({
            type: 'error',
            text1: t('eContract.LG.TxtErrorSignAccountOutsideOrganization'),
          });
        }
      });
    }
  };
  const onBlurEmail = () => {
    if (!isEmpty(email)) {
      setErrorMessage('');
    } else {
      setErrorMessage(t('eContract.LG.messageValidate.emailIsEmpty'));
    }
  };
  const onBlurAccessCode = () => {
    if (!isEmpty(password)) {
      setErrorPassword('');
    } else {
      setErrorPassword(t('eContract.LG.AccessCodeIsEmpty'));
    }
  };

  const handleNaviLogin = () => {
    isAuthorized
      ? navigation.dispatch(StackActions.replace(NavigationName.HomeScreen))
      : navigation.dispatch(StackActions.replace(NavigationName.SignInScreen));
  };

  return (
    <ImageBackground source={BgOnboarding} style={[styles.ctnMain]}>
      <TouchableWithoutFeedback onPress={hideKeyboard}>
        <SafeAreaView style={[styles.viewArea]}>
          <View style={styles.viewLogo}>
            <ChangeLanguage />
            <LogoEcontract width={190} height={60} />
          </View>

          <View style={[styles.viewSignIn]}>
            <View style={[styles.containerSignIn]}>
              <TextCM style={[styles.headerStyle]}>
                {t('eContract.LG.verifiedLogin')}
              </TextCM>
              <TextFieldCM
                value={email}
                onChangeText={setEmail}
                onBlur={onBlurEmail}
                label={t('eContract.LG.EmailOrPhoneNumber')}
                isRequired={true}
                errorMessage={errorMessage}
                placeholder={t('eContract.LG.EnterEmailOrPhoneNumber')}
                containerStyle={[styles.containerTextField]}
                inputContainerStyle={{backgroundColor: 'white'}}
              />
              <TextFieldCM
                value={password}
                onChangeText={setPassword}
                label={t('eContract.LG.EnterTheAccessCode')}
                isRequired={true}
                onBlur={onBlurAccessCode}
                secureTextEntry={isSecureText}
                errorMessage={errorPassword}
                placeholder={t('eContract.LG.EnterTheAccessCode')}
                containerStyle={[
                  styles.containerTextField,
                  styles.ctnInputField,
                ]}
                inputContainerStyle={{backgroundColor: 'white'}}
                onIconPress={() => setIsSecureText(!isSecureText)}
                viewIconRight={
                  isSecureText ? (
                    <EyesIcon width={24} height={24} />
                  ) : (
                    <EyesIconOpen width={24} height={24} />
                  )
                }
              />
              <ButtonCM
                label={t('eContract.LG.Access')}
                onPress={onAccess}
                style={[styles.containerBtn]}
                styleLabel={styles.labelStyle}
                loading={false}
              />
              <TextCM style={{marginBottom: 20, textAlign: 'center'}}>
                <TextCM
                  onPress={handleNaviLogin}
                  style={[styles.textCreateAccount]}>
                  {isAuthorized ? t('eContract.RG.GoHome') : t('eContract.RG.BtnLogin')}
                </TextCM>
              </TextCM>
            </View>
          </View>
        </SafeAreaView>
      </TouchableWithoutFeedback>
    </ImageBackground>
  );
};

export default SignAccountOutsideOrganization;
