import {createNativeStackNavigator} from '@react-navigation/native-stack';
import {EvaIconsPack} from '@ui-kitten/eva-icons';
import {ApplicationProvider, IconRegistry} from '@ui-kitten/components';
import * as eva from '@eva-design/eva';
import {default as mapping} from '../../../mapping.json';
import React from 'react';
import {NavigationName} from '../../constants';
import SignatureWebview from '../../screens/notification/signature-flow';
import SignAccountOutsideOrganization from '../../screens/sign-account-outside-organization';

const Stack = createNativeStackNavigator();

const SignOutSideNavigation = (props: any) => {
  return (
    <>
      <IconRegistry icons={[EvaIconsPack]} />
      <ApplicationProvider
        customMapping={mapping as any}
        {...eva}
        theme={{...eva.light}}>
        <Stack.Navigator
          screenOptions={{
            headerShown: false,
          }}>
          <Stack.Screen
            initialParams={props}
            name={NavigationName.SignAccountOutsideOrganizationScreen}
            component={SignAccountOutsideOrganization}
          />
          <Stack.Screen
            name={NavigationName.SignatureWebview}
            component={SignatureWebview}
          />
        </Stack.Navigator>
      </ApplicationProvider>
    </>
  );
};

export default SignOutSideNavigation;
