import {View, Text, TouchableOpacity} from 'react-native';
import React, {useState} from 'react';
import styles from './styles';
import {
  IconBlackDown,
  IconBlackUp,
  IconEngland,
  IconVietNam,
} from '../../../../assets/images';
import {Language} from '../../../settings';
import {useAppDispatch, useAppSelector} from '../../../../hook/useRedux';
import {commonActions} from '../../../../redux/slices';
import {useTranslation} from 'react-i18next';

const LIST_LANGUAGES = [
  {
    type: Language.VietNam,
    icon: <IconVietNam width={28} height={18} />,
  },
  {
    type: Language.English,
    icon: <IconEngland width={28} height={18} />,
  },
];

const ChangeLanguage = () => {
  const {i18n} = useTranslation();
  const dispatch = useAppDispatch();
  const language =
    useAppSelector(state => state.common.language) || Language.VietNam;
  const [showList, setShowList] = useState(false);

  const onChangeLanguage = (type: Language) => {
    dispatch(commonActions.setLanguage(type));
    i18n.changeLanguage(type);
  };

  const getCurrentIconLanguage = () => {
    if (language === Language.VietNam) {
      return <IconVietNam width={28} height={18} />;
    }
    return <IconEngland width={28} height={18} />;
  };

  const toggleShowList = () => {
    setShowList(!showList);
  };

  const getListMoreLanguage = () => {
    const more = LIST_LANGUAGES.filter(
      item => item.type !== (language || Language.VietNam),
    );
    return more.map(item => {
      return (
        <TouchableOpacity
          style={styles.btnChange}
          key={item.type}
          onPress={() => {
            onChangeLanguage(item.type);
            toggleShowList();
          }}>
          {item.icon}
        </TouchableOpacity>
      );
    });
  };

  return (
    <View style={styles.viewCtn}>
      <TouchableOpacity style={styles.btnChange} onPress={toggleShowList}>
        {getCurrentIconLanguage()}
        {!showList ? (
          <IconBlackDown width={16} height={16} />
        ) : (
          <IconBlackUp width={16} height={16} />
        )}
      </TouchableOpacity>
      {showList && getListMoreLanguage()}
    </View>
  );
};

export default ChangeLanguage;
